"""Critical Thinking & Verbal Ability: hand-authored. (stem, correct, [3 wrong], explanation)"""
V = []
def add(q, a, w, s): V.append(dict(q=q, ans=a, wrongs=w, sol=s))

ERR = "Identify the part of the sentence that contains the error."
# --- error spotting
add(f"{ERR}<br><i>Neither of the two candidates have submitted their forms on time.</i>", "have submitted", ["Neither of", "their forms", "on time"], "‘Neither’ takes a singular verb: <b>has</b> submitted.")
add(f"{ERR}<br><i>The committee has decided to postpone it's meeting until further notice.</i>", "it's meeting", ["The committee has", "to postpone", "until further notice"], "<b>it's</b> = it is. The possessive is <b>its</b>.")
add(f"{ERR}<br><i>She is one of those teachers who always encourages students to ask questions.</i>", "always encourages", ["She is one of", "those teachers who", "to ask questions"], "‘who’ refers to the plural ‘teachers’, so the verb is plural: <b>encourage</b>.")
add(f"{ERR}<br><i>Each of the boys were given a certificate.</i>", "were given", ["Each of", "the boys", "a certificate"], "‘Each’ is singular: <b>was</b> given.")
add(f"{ERR}<br><i>The news about the floods were shocking.</i>", "were shocking", ["The news", "about the floods", "No error"], "‘News’ is an uncountable singular noun: <b>was</b> shocking.")
add(f"{ERR}<br><i>I have been knowing him since childhood.</i>", "have been knowing", ["I", "since", "childhood"], "‘Know’ is a stative verb and is not used in the continuous form: <b>have known</b>.")
add(f"{ERR}<br><i>Hardly had she entered the room when the lights went out.</i>", "No error", ["Hardly had", "when", "went out"], "‘Hardly … when’ with inversion is correct.")
add(f"{ERR}<br><i>If I would have known the answer, I would have told you.</i>", "If I would have known", ["I would have told", "the answer", "you"], "Third conditional: <b>If I had known</b>, I would have told you.")
add(f"{ERR}<br><i>The number of applicants have increased this year.</i>", "have increased", ["The number of", "applicants", "this year"], "‘The number of’ is singular: <b>has</b> increased. (‘A number of’ would be plural.)")
add(f"{ERR}<br><i>Scarcely had the meeting begun than the power failed.</i>", "than the power failed", ["Scarcely had", "the meeting begun", "No error"], "‘Scarcely’ pairs with <b>when</b>, not ‘than’.")
add(f"{ERR}<br><i>The furniture in the hall are old but sturdy.</i>", "are old", ["The furniture", "in the hall", "but sturdy"], "‘Furniture’ is uncountable: <b>is</b> old.")
add(f"{ERR}<br><i>He suggested that she should takes a gap year.</i>", "should takes", ["He suggested", "that she", "a gap year"], "After a modal the base verb is used: <b>should take</b>.")
add(f"{ERR}<br><i>Despite of the heavy rain, the match continued.</i>", "Despite of", ["the heavy rain", "the match", "continued"], "‘Despite’ is never followed by ‘of’ (compare ‘in spite of’).")
add(f"{ERR}<br><i>She is more cleverer than her sister.</i>", "more cleverer", ["She is", "than", "her sister"], "Double comparative. Use <b>cleverer</b> or <b>more clever</b>.")
add(f"{ERR}<br><i>He prefers walking than cycling to school.</i>", "than cycling", ["He prefers", "walking", "to school"], "‘Prefer’ takes <b>to</b>: prefers walking <b>to</b> cycling.")
add(f"{ERR}<br><i>I look forward to meet you next week.</i>", "to meet", ["I look forward", "you", "next week"], "‘Look forward to’ takes a gerund: look forward to <b>meeting</b>.")
# --- sentence improvement
add("Choose the best way to rewrite the sentence.<br><i>Having finished the report, the lights were switched off by Mira.</i>", "Having finished the report, Mira switched off the lights.", ["Having finished the report, the lights were switched off by Mira.", "Having finished the report, the lights were switched off.", "The lights, having finished the report, were switched off by Mira."], "A participial phrase must modify the subject that did the action. Lights cannot ‘finish a report’ (dangling modifier).")
add("Choose the sentence that is grammatically correct.", "The principal, along with the teachers, is planning a trip.", ["The principal, along with the teachers, are planning a trip.", "The principal, along with the teachers, planning a trip is.", "The principal, along with the teachers, were planning a trip."], "‘Along with’ phrases do not change the number of the subject; the subject is the singular ‘principal’.")
add("Choose the correct rephrasing.<br><i>No sooner did he sit down, the phone rang.</i>", "No sooner had he sat down than the phone rang.", ["No sooner did he sat down than the phone rang.", "No sooner he sat down when the phone rang.", "No sooner had he sit down than the phone rang."], "‘No sooner’ + past perfect (had + V3) + <b>than</b>.")
add("Choose the best option to complete: <i>Unless you ______ harder, you will not pass.</i>", "work", ["do not work", "will work", "worked not"], "‘Unless’ already carries the negative, so the verb is positive; present tense in a first conditional.")
add("Select the correctly punctuated sentence.", "Although it was late, we decided to finish the match.", ["Although it was late we, decided to finish the match.", "Although, it was late we decided to finish the match.", "Although it was late; we decided, to finish the match."], "A comma follows a fronted subordinate clause; no other commas are needed.")
add("Choose the correct preposition: <i>She is allergic ______ peanuts.</i>", "to", ["with", "from", "against"], "Fixed collocation: allergic <b>to</b>.")
# --- vocabulary
def fill(stem, a, w, s): add("Choose the word that best completes the sentence.<br><i>" + stem + "</i>", a, w, s)
fill("Her ______ remarks during the debate hurt several colleagues.", "acerbic", ["affable", "lucid", "ornate"], "Acerbic = sharp, harsh. Affable (friendly) could not ‘hurt’.")
fill("The manager's ______ explanation left everyone more confused than before.", "convoluted", ["succinct", "forthright", "cogent"], "Convoluted = needlessly complicated; the other three would reduce confusion.")
fill("Despite years of training, he remained ______ about his abilities.", "diffident", ["boastful", "jubilant", "intrepid"], "Diffident = lacking self-confidence; ‘despite’ signals a contrast with expected confidence.")
fill("The drought had a ______ effect on the harvest, leaving farmers with almost nothing.", "devastating", ["negligible", "salutary", "trivial"], "The clause after the comma shows the effect was severe.")
fill("Scientists must remain ______; they should not accept a claim without evidence.", "sceptical", ["credulous", "gullible", "complacent"], "Sceptical = demanding evidence. Credulous and gullible mean the opposite.")
fill("The brothers had a ______ relationship; they would quarrel and reconcile within minutes.", "volatile", ["placid", "formal", "distant"], "Volatile = liable to change rapidly.")
fill("Her ______ approach, checking every figure twice, made her an excellent auditor.", "meticulous", ["cursory", "haphazard", "indolent"], "Meticulous = extremely careful, matching ‘checking every figure twice’.")
fill("The new policy was designed to ______ the effects of inflation on the poor.", "mitigate", ["exacerbate", "aggravate", "intensify"], "Mitigate = lessen. The other three would worsen the effects.")
fill("He was ______ by nature, always avoiding company and conversation.", "reclusive", ["gregarious", "garrulous", "convivial"], "Reclusive = withdrawn from society.")
fill("The judge's verdict was ______; no one could accuse her of favouring either side.", "impartial", ["partisan", "biased", "capricious"], "Impartial = treating all sides equally.")
fill("Frequent power cuts ______ the factory's production schedule.", "disrupted", ["facilitated", "expedited", "augmented"], "Only ‘disrupted’ fits a negative cause (power cuts).")
add("Choose the word closest in meaning to <b>ephemeral</b>.", "short-lived", ["eternal", "fragile", "ancient"], "Ephemeral (from Greek, ‘lasting a day’) = lasting a very short time.")
add("Choose the word opposite in meaning to <b>candid</b>.", "evasive", ["frank", "honest", "blunt"], "Candid = open and honest; its opposite is evasive.")
add("Choose the word closest in meaning to <b>ubiquitous</b>.", "omnipresent", ["rare", "ambiguous", "ancient"], "Ubiquitous = found everywhere.")
add("Choose the word opposite in meaning to <b>frugal</b>.", "extravagant", ["thrifty", "prudent", "austere"], "Frugal = careful with money; extravagant is its opposite.")
# --- critical reasoning
def cr(stem, a, w, s): add(stem, a, w, s)
cr("All shops on Park Road close by 9 pm. Some shops on Park Road sell electronics.<br>Which conclusion is best supported?", "Some shops that sell electronics close by 9 pm.", ["All electronics shops in the city close by 9 pm.", "Shops outside Park Road stay open late.", "No shop on Park Road is open after 8 pm."], "Electronics shops on Park Road are Park Road shops, and all of those close by 9 pm. The rest go beyond the information.")
cr("A city made buses free on Sundays. Sunday car traffic then fell 15%.<br>Which finding most strengthens the claim that free buses caused the fall?", "On weekdays, when buses were not free, car traffic did not fall over the same period.", ["Petrol prices fell sharply in the same months.", "Many residents leave town on Sundays.", "Bus companies reported higher weekday revenue."], "A comparison group with no free buses and no fall rules out general causes. The other options are irrelevant or point to other explanations.")
cr("“Our school should buy tablets for every student, because students who own tablets score higher.”<br>What is the key assumption?", "Tablets help raise scores, rather than high scorers simply being more likely to own tablets.", ["All schools can afford tablets.", "Students dislike printed books.", "Tablets cost less than books."], "The argument moves from correlation to cause; it assumes the causal direction.")
cr("“Sales of Brand X rose after it hired a famous actor, so the advertisement caused the rise.”<br>Which statement most weakens this?", "A major rival's product was recalled that same month, sending buyers to Brand X.", ["The actor is popular among teenagers.", "Brand X's price stayed the same.", "The advertisement was shown on television."], "An alternative cause (rival recall) explains the rise.")
cr("No reptile is warm-blooded. All snakes are reptiles.<br>Which must be true?", "No snake is warm-blooded.", ["Some snakes are warm-blooded.", "All reptiles are snakes.", "Some warm-blooded animals are reptiles."], "Snakes ⊂ reptiles, and reptiles have no overlap with warm-blooded animals, so neither do snakes.")
cr("Rohan scored lower in maths than in science. His science score was lower than his English score.<br>Which conclusion is certain?", "Rohan scored highest in English.", ["Rohan scored lowest in English.", "Rohan scored the same in science and English.", "Rohan likes science more than English."], "Maths < Science < English, so English is the highest.")
cr("“People who drink coffee live longer, so coffee extends life.”<br>What is the flaw?", "It treats a correlation as proof of cause.", ["It relies on an expert's opinion.", "It uses a very small sample.", "It contradicts itself."], "Other factors (wealth, healthcare, lifestyle) may explain both coffee drinking and longevity.")
cr("“Every player in the team is excellent, so the team is excellent.”<br>The reasoning is flawed because it assumes:", "what is true of each part must be true of the whole.", ["all teams have excellent players.", "excellence cannot be measured.", "the team has no weak player."], "Fallacy of composition: a team also depends on coordination, not just individual skill.")
cr("In 2020, 40% of households in Town A owned a car; in 2025, 52% did.<br>Which conclusion is valid?", "The share of car-owning households rose by 12 percentage points.", ["The number of cars rose by 30%.", "The town's population grew.", "Public transport use fell."], "52 − 40 = 12 percentage points. A rise from 40% to 52% is 30% in <i>relative</i> terms but that is about the share, not the number of cars; population data is absent.")
cr("“Please carry your ID card to enter the exam hall.”<br>Which assumption underlies this instruction?", "An ID card helps the invigilators to verify the candidate's identity.", ["No candidate will forget their ID.", "The hall has limited seating.", "ID cards are free for all."], "The instruction only makes sense if an ID serves a verification purpose.")
cr("A bakery's sales rose 20% this year, yet its profits fell.<br>Which statement best resolves the apparent paradox?", "The cost of ingredients rose faster than the bakery's prices.", ["Customers prefer fresh bread.", "The bakery opened an hour earlier.", "Sales rose mainly around festivals."], "If costs rise faster than revenue, higher sales can still shrink profit.")
cr("Only members can borrow books from the club library. Meera borrowed a book.<br>What follows?", "Meera is a member.", ["Meera is the librarian.", "All members borrow books.", "Meera borrowed more than one book."], "Borrowing requires membership; the converse (all members borrow) does not follow.")
cr("Anyone who qualifies must have scored at least 60%. Tara scored 55%.<br>What follows?", "Tara does not qualify.", ["Tara qualifies if she appeals.", "Everyone scoring 60% qualifies.", "Tara scored the lowest."], "A necessary condition (≥ 60%) is not met, so she cannot qualify. A necessary condition is not a sufficient one.")
cr("Statement: ‘Ban plastic bags in the city.’<br>Which argument is strongest in favour?", "Plastic bags clog drains and cause flooding in the city.", ["Plastic bags are cheap.", "Many people use plastic bags.", "Other cities allow plastic bags."], "A strong argument is relevant and specific to the proposal's goal (harm to the city).")
# --- sequencing / odd one out
add("Arrange the sentences in order.<br>P. Nobody noticed the leak at first.<br>Q. By morning the whole basement was flooded.<br>R. A small drip began in the pipe overnight.<br>S. Slowly it widened into a steady stream.", "RPSQ", ["PRSQ", "RSPQ", "QRPS"], "R introduces the drip, P (‘at first’) follows, S shows it widening, Q is the result.")
add("Arrange the sentences in order.<br>P. The bus finally arrived, an hour late.<br>Q. We had been waiting at the stop since six.<br>R. By then the rain had become a storm.<br>S. All of us were soaked.", "QPRS", ["PQRS", "QRPS", "SQPR"], "Waiting (Q) → the late bus (P) → the storm by then (R) → soaked (S).")
add("Four sentences are given; one does not fit the paragraph. Identify it.<br>P. Honeybees communicate through dance.<br>Q. A bee's waggle shows the direction of the flowers.<br>R. Elephants live in matriarchal herds.<br>S. The length of the waggle signals distance.", "R", ["P", "Q", "S"], "P, Q and S are about bee dances; R is about elephants.")
add("Four sentences are given; one does not fit the paragraph. Identify it.<br>P. Solar panels convert sunlight into electricity.<br>Q. Dust on the panels lowers their output.<br>R. The Himalayas were formed by a tectonic collision.<br>S. Regular cleaning keeps panels efficient.", "R", ["P", "Q", "S"], "R is geology; the rest are about solar panels.")
add("Choose the option that best captures the main idea.<br><i>Cities that plant trees along roads see cooler summers, cleaner air and calmer traffic. Yet most councils cut tree-planting budgets first.</i>", "Tree-planting has several benefits but is undervalued in budgets.", ["Trees are expensive to maintain.", "Traffic is the main problem of cities.", "Councils should stop cutting budgets."], "The passage lists benefits and then the contrasting neglect; the best summary joins the two.")
